# Most HPC sites firewall outbound HTTPS from compute nodes; Kit needs S3
# access to fetch USD assets and wandb needs the API. Set HTTP(S)_PROXY to
# your site's proxy (FAU NHR Alex: http://proxy.nhr.fau.de:80). Pass an empty
# string to disable. http://proxy.nhr.fau.de:80 is the renderer-injected default.
export HTTP_PROXY=${HTTP_PROXY-http://proxy.nhr.fau.de:80}
export HTTPS_PROXY=${HTTPS_PROXY-http://proxy.nhr.fau.de:80}
export NO_PROXY=${NO_PROXY:-localhost,127.0.0.1,.fau.de,.nhr.fau.de,.rrze.uni-erlangen.de}

